"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:1109-07-31:0":{"b": ["Veziri Ahmed b. Nizamulmulku u dërgua në Alamut me një ushtri të madhe; për shkak të dimrit nuk u arrit rezultat", "ba5263e5"], "d": ["Sulltani selxhuk Muhamed Tapar, për ta zhdukur Hasan Sabbahun, dërgoi mbi Alamut vezirin e tij Ahmed b. Nizamulmulk me një ushtri të madhe; fushata mbeti pa rezultat për shkak të dimrit. Rrethimi kryesor do të vinte në 1117.", "2e2a9c88"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:1113-06-18:0":{"b": ["Në Alep u vranë shumë batinitë bashkë me përfaqësuesit e Hasan Sabbahut në Siri", "c70cc81f"], "d": ["Sulltani selxhuk Muhamed Tapar kërkoi nga meliku i Alepit Alparslan el-Ahras dhe nga reisul-ahdasi Said b. Bedi që batinitët në qytet të vriteshin; u vranë shumë batinitë bashkë me përfaqësuesit e Hasan Sabbahut në Siri, si Ebu Tahir es-Saig, Ismail ed-Dai dhe vëllai i Hakim el-Munexhximit (507/1113).", "c7adbffa"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:1117-01-01:0":{"b": ["Dinastia annazide mori fund (sipas shënimit të Ibn el-Athirit për 130 vjet)", "a533a1d6"], "d": ["Dinastia annazide mori fund (sipas shënimit të Ibn el-Athirit për 130 vjet)", "a533a1d6"]},
