"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:1137-01-01:0":{"b": ["Fatiku II u vra; Fatiku III b. Muhamed u bë sundimtar, Sururi vezir (531).", "2f2d69ac"], "d": ["Fatiku II u vra; Fatiku III b. Muhamed u bë sundimtar, Sururi vezir (531).", "2f2d69ac"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:1141-01-01:0":{"b": ["Pas fitores së Katvanit, horezmshahët pranuan të bëheshin vasalë të karakitajëve dhe të paguanin haraç", "5719a5ee"], "d": ["Pasi karakitajët mundën Sanxharin në Katvan dhe u bënë zotër të tërë Maverannehrit, po atë vit edhe horezmshahët pranuan t'u nënshtroheshin karakitajëve si vasalë dhe t'u paguanin haraç (30.000 dinarë në vit). Kjo varësi vazhdoi deri në 1173, kur Tekishi me përkrahjen karakitajase hipi në fronin e Horezmit.", "ab6f992b"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:1141-01-01:1":{"b": ["Kakujidi i fundit vdiq në betejën e Katvanit; në Jazd vendin e tyre e zunë atabegët e Jazdit", "272bdc16"], "d": ["Kakujidi i fundit vdiq në betejën e Katvanit; në Jazd vendin e tyre e zunë atabegët e Jazdit", "272bdc16"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:1142-02-01:0":{"b": ["Gur Hani Yeh-lü Ta-shi vdiq; vendin e tij e zuri gruaja e tij Kujang (Tu-pu-yen)", "29e8156e"], "d": ["Sundimtari i parë karakitaj, Gur Hani Yeh-lü Ta-shi (1130-1142), vdiq në shkurt 1142 (ose 1143); e pasuan me radhë gruaja e tij Tu-pu-yen (Kujang), i biri Yeh-lü Yi-lie, motra e tij Yeh-lü-she ose regjentja Pu-su-wan. Me fitoren e Katvanit (1141) tërë Maverannehri dhe Horezmi ishin vënë nën tatim.", "5412642d"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:1150-01-01:0":{"b": ["Umu Fatik Alemi vdiq; Sururi përqendroi në dorën e vet të gjithë pushtetin (545).", "5a5e3fcd"], "d": ["Umu Fatik Alemi vdiq; Sururi përqendroi në dorën e vet të gjithë pushtetin (545).", "5a5e3fcd"]},
